#include <vector>
#include <list>

void sequence_erase_loop(std::vector<int>& v) {
    for (auto it = v.begin(); it != v.end(); ) {
        if (*it % 2 == 0) {
            // Must use the return value to get the next valid iterator
            it = v.erase(it); 
        } else {
            ++it;
        }
    }
}

void assoc_erase_loop(std::list<int>& l) {
    for (auto it = l.begin(); it != l.end(); ) {
        if (*it == 5) {
            // For containers with stable iterators (list, map), advance first
            it = l.erase(it); 
        } else {
            ++it;
        }
    }
}
